tests.command:
cd backend && ENV=development DATABASE_URL=sqlite:////tmp/t29ac.db JWT_SECRET=t29repro-0123456789-abcdefghijklmnopqrstuvwxyz-abcd1234 STAFF_PIN=0000 TZ=UTC ./.venv/Scripts/python.exe -c "
  from app.schemas import CreateTableRequest as C, UpdateTableRequest as U
  def conds(s):
      out=[]
      def rec(x):
          if isinstance(x,dict):
              for k,v in x.items():
                  if k in ('minimum','maximum','minLength','maxLength'): out.append((k,v))
                  rec(v)
          elif isinstance(x,list):
              for v in x: rec(v)
      rec(s); return dict(out)
  cs=conds(C.model_json_schema()['properties']['sort_order'])
  assert 'minimum' in cs and 'maximum' in cs, ('CreateTableRequest.sort_order unbounded', cs)
  us=conds(U.model_json_schema()['properties']['sort_order'])
  assert 'minimum' in us and 'maximum' in us, ('UpdateTableRequest.sort_order unbounded', us)
  uc=conds(U.model_json_schema()['properties']['capacity'])
  assert uc.get('minimum')==1 and uc.get('maximum')==20, ('UpdateTableRequest.capacity', uc)
  ul=conds(U.model_json_schema()['properties']['label'])
  assert ul.get('minLength')==1 and ul.get('maxLength')==10, ('UpdateTableRequest.label', ul)
  print('ac1 ok')
  "

cd backend
SHA_BEFORE=$(sha256sum test.db | cut -d' ' -f1)
MT_BEFORE=$(stat -c '%Y' test.db)
ENV=development DATABASE_URL=sqlite:///./test.db JWT_SECRET=t35repro-0123456789-abcdefghijklmnopqrstuvwxyz-abcd1234 STAFF_PIN=0000 TZ=UTC ./.venv/Scripts/python.exe -m pytest tests/test_log_hygiene.py::test_500_traceback_is_redacted -q -p no:randomly
RC=$?
SHA_AFTER=$(sha256sum test.db | cut -d' ' -f1)
MT_AFTER=$(stat -c '%Y' test.db)
git checkout -- test.db
[ $RC -eq 0 ] || { echo "ac3 FAIL: corruption test itself failed"; exit 1; }
[ "$SHA_BEFORE" = "$SHA_AFTER" ] && [ "$MT_BEFORE" = "$MT_AFTER" ] || { echo "ac3 FAIL: the corruption test still rewrites the shared engine file backend/test.db"; exit 1; }
[ ! -f test.db-wal ] && [ ! -f test.db-shm ] || { echo "ac3 FAIL: WAL sidecars of the shared file left behind"; exit 1; }
grep -q 'engine.dispose()' tests/test_log_hygiene.py || { echo "ac3 FAIL: shared engine not disposed in the hygiene module"; exit 1; }
echo "ac3 ok: corruption test isolated from the shared engine file"

cd backend
COLLECTED=$(ENV=development DATABASE_URL=sqlite:///./test.db JWT_SECRET=t35repro-0123456789-abcdefghijklmnopqrstuvwxyz-abcd1234 STAFF_PIN=0000 TZ=UTC ./.venv/Scripts/python.exe -m pytest tests/test_log_hygiene.py tests/test_db_atomicity.py --collect-only -q -p no:randomly | grep -c '::test_')
[ "$COLLECTED" = "10" ] || { echo "ac5 FAIL: expected 10 collected tests, got $COLLECTED"; exit 1; }
SUMMARY=$(ENV=development DATABASE_URL=sqlite:///./test.db JWT_SECRET=t35repro-0123456789-abcdefghijklmnopqrstuvwxyz-abcd1234 STAFF_PIN=0000 TZ=UTC ./.venv/Scripts/python.exe -m pytest tests/test_log_hygiene.py tests/test_db_atomicity.py -q -p no:randomly | tail -1)
echo "$SUMMARY" | grep -q '8 passed, 2 xfailed' || { echo "ac5 FAIL: pair summary changed: $SUMMARY"; exit 1; }
git checkout -- test.db
HYG=$(grep -c 'assert ' tests/test_log_hygiene.py)
ATM=$(grep -c 'assert ' tests/test_db_atomicity.py)
[ "$HYG" -ge 22 ] && [ "$ATM" -ge 38 ] || { echo "ac5 FAIL: assertion lines reduced (hygiene=$HYG <22 or atomicity=$ATM <38)"; exit 1; }
echo "ac5 ok: no assertion weakening (invariant, passes pre-fix by design)"

cd backend
COLLECTED=$(ENV=development DATABASE_URL=sqlite:///./test.db JWT_SECRET=t36baseline-0123456789-abcdefghijklmnopqrstuvwxyz STAFF_PIN=0000 TZ=UTC ./.venv/Scripts/python.exe -m pytest tests/test_rate_limit_t23.py --collect-only -q -p no:randomly | grep -c '::test_')
[ "$COLLECTED" = "7" ] || { echo "ac5 FAIL: expected 7 collected tests, got $COLLECTED"; exit 1; }
SUMMARY=$(ENV=development DATABASE_URL=sqlite:///./test.db JWT_SECRET=t36baseline-0123456789-abcdefghijklmnopqrstuvwxyz STAFF_PIN=0000 TZ=UTC ./.venv/Scripts/python.exe -m pytest tests/test_rate_limit_t23.py -q -p no:randomly | tail -1)
echo "$SUMMARY" | grep -q '7 passed' || { echo "ac5 FAIL: file summary changed: $SUMMARY"; exit 1; }
git checkout -- test.db
ASSERTS=$(grep -c 'assert ' tests/test_rate_limit_t23.py)
[ "$ASSERTS" -ge 27 ] || { echo "ac5 FAIL: assertion lines reduced ($ASSERTS < 27)"; exit 1; }
echo "ac5 ok: no assertion weakening (invariant, passes pre-fix by design)"

[ -z "$(git status --porcelain backend/app)" ] || { echo "ac6 FAIL: backend/app has working-tree changes"; exit 1; }
[ -z "$(git diff --name-only HEAD -- backend/app)" ] || { echo "ac6 FAIL: backend/app differs from HEAD"; exit 1; }
echo "ac6 ok: no production code changes (test-infra only)"

cd backend
OUT=$(ENV=development DATABASE_URL=sqlite:///./test.db JWT_SECRET=t13groom-0123456789-abcdefghijklmnopqrstuvwxyz STAFF_PIN=0000 TZ=UTC ./.venv/Scripts/python.exe -m pytest -q -p no:randomly -rx 2>&1)
RC=$?
git checkout -- test.db
SUMMARY=$(echo "$OUT" | grep -E "[0-9]+ (passed|failed|error)" | tail -1)
echo "$SUMMARY"
[ $RC -eq 0 ] || { echo "ac1 FAIL: TZ=UTC suite exited $RC"; exit 1; }
echo "$SUMMARY" | grep -qE "[0-9]+ passed, 2 xfailed" || { echo "ac1 FAIL: TZ=UTC summary is not 'N passed, 2 xfailed': $SUMMARY"; exit 1; }
PASSED=$(echo "$SUMMARY" | grep -oE "^[0-9]+ passed" | grep -oE "[0-9]+")
[ "$PASSED" -ge 274 ] || { echo "ac1 FAIL: TZ=UTC passed floor shrank ($PASSED < 274)"; exit 1; }
[ "$(echo "$OUT" | grep -c '^XFAIL')" = "2" ] || { echo "ac1 FAIL: TZ=UTC xfail set size is not 2"; exit 1; }
echo "$OUT" | grep -q '^XFAIL tests/test_db_atomicity.py::test_half_write_table_available_party_still_seated' || { echo "ac1 FAIL: TZ=UTC xfail set changed (missing test_half_write_table_available_party_still_seated)"; exit 1; }
echo "$OUT" | grep -q '^XFAIL tests/test_db_atomicity.py::test_half_write_table_occupied_entry_seated_before_the_commit' || { echo "ac1 FAIL: TZ=UTC xfail set changed (missing test_half_write_table_occupied_entry_seated_before_the_commit)"; exit 1; }
echo "ac1 ok (UTC): $PASSED passed, 2 xfailed (set unchanged), 0 failed"

cd backend
OUT=$(ENV=development DATABASE_URL=sqlite:///./test.db JWT_SECRET=t13groom-0123456789-abcdefghijklmnopqrstuvwxyz STAFF_PIN=0000 TZ=Asia/Taipei ./.venv/Scripts/python.exe -m pytest -q -p no:randomly -rx 2>&1)
RC=$?
git checkout -- test.db
SUMMARY=$(echo "$OUT" | grep -E "[0-9]+ (passed|failed|error)" | tail -1)
echo "$SUMMARY"
[ $RC -eq 0 ] || { echo "ac1 FAIL: TZ=Asia/Taipei suite exited $RC"; exit 1; }
echo "$SUMMARY" | grep -qE "[0-9]+ passed, 2 xfailed" || { echo "ac1 FAIL: TZ=Asia/Taipei summary is not 'N passed, 2 xfailed': $SUMMARY"; exit 1; }
PASSED=$(echo "$SUMMARY" | grep -oE "^[0-9]+ passed" | grep -oE "[0-9]+")
[ "$PASSED" -ge 274 ] || { echo "ac1 FAIL: TZ=Asia/Taipei passed floor shrank ($PASSED < 274)"; exit 1; }
[ "$(echo "$OUT" | grep -c '^XFAIL')" = "2" ] || { echo "ac1 FAIL: TZ=Asia/Taipei xfail set size is not 2"; exit 1; }
echo "$OUT" | grep -q '^XFAIL tests/test_db_atomicity.py::test_half_write_table_available_party_still_seated' || { echo "ac1 FAIL: TZ=Asia/Taipei xfail set changed (missing test_half_write_table_available_party_still_seated)"; exit 1; }
echo "$OUT" | grep -q '^XFAIL tests/test_db_atomicity.py::test_half_write_table_occupied_entry_seated_before_the_commit' || { echo "ac1 FAIL: TZ=Asia/Taipei xfail set changed (missing test_half_write_table_occupied_entry_seated_before_the_commit)"; exit 1; }
echo "ac1 ok (Asia/Taipei): $PASSED passed, 2 xfailed (set unchanged), 0 failed"

cd frontend
npx tsc --noEmit
TSC_RC=$?
[ $TSC_RC -eq 0 ] || { echo "ac2 FAIL: tsc --noEmit exited $TSC_RC (want 0 errors)"; exit 1; }
npm run lint
LINT_RC=$?
[ $LINT_RC -eq 0 ] || { echo "ac2 FAIL: eslint exited $LINT_RC (want clean)"; exit 1; }
OUT=$(npm test 2>&1)
VT_RC=$?
echo "$OUT" | grep -E "Test Files|Tests "
[ $VT_RC -eq 0 ] || { echo "ac2 FAIL: vitest exited $VT_RC"; exit 1; }
echo "$OUT" | grep -q "Test Files  30 passed (30)" || { echo "ac2 FAIL: vitest test files are not at the approved floor of 30: $(echo "$OUT" | grep 'Test Files')"; exit 1; }
echo "$OUT" | grep -q "Tests  267 passed (267)" || { echo "ac2 FAIL: vitest tests are not at the approved floor of 267: $(echo "$OUT" | grep 'Tests ')"; exit 1; }
echo "ac2 ok: tsc 0 errors, lint clean, vitest 30 files / 267 tests (approved new floors)"

[ -z "$(git status --porcelain -- backend/app backend/tests frontend/src frontend/package.json frontend/package-lock.json)" ] || { echo "ac5 FAIL: product files changed - this issue is verification + floor recording only"; exit 1; }
grep -q "30 files / 267 tests" docs/issues/t13.md || { echo "ac5 FAIL: the approved new frontend floors (30 files / 267 tests) are not recorded in the spec"; exit 1; }
grep -q "388 passed, 2 xfailed" docs/issues/t13.md || { echo "ac5 FAIL: the two-TZ groom baseline (388 passed, 2 xfailed) is not recorded in the spec"; exit 1; }
echo "ac5 ok: no product change; approved floors and two-TZ baseline recorded in the spec"
